<template>
	<view class="page">
		<AchievementUnlockNotifier />
		<view class="header">
			<text class="header-title">流利跟读</text><text class="header-sub">听原句后完整跟读，评分达到 80 分才算通过</text>
			<view class="progress"><view class="progress-fill" :style="{ width: progressPercent + '%' }"></view></view>
			<text class="progress-text">{{ completed ? '训练完成' : `${currentIndex + 1} / ${sentences.length || 3}` }}</text>
		</view>
		<view v-if="loading" class="state"><text class="state-icon">🎧</text><text>正在准备跟读句子...</text></view>
		<view v-else-if="loadError" class="state"><text class="state-icon">📭</text><text>{{ loadError }}</text><button class="secondary" @click="loadSentences">重新加载</button></view>
		<view v-else-if="completed" class="complete-card">
			<view class="complete-icon">🎉</view><text class="complete-title">今日跟读完成</text><text class="complete-desc">已完成 {{ passedCount }} 句合格跟读，练习结果已记录</text>
			<view class="complete-score"><text>本组平均分</text><text>{{ averageScore }} 分</text></view><button class="primary" @click="goBack">完成并返回</button>
		</view>
		<view v-else-if="currentSentence" class="practice-card">
			<view class="sentence-index">第 {{ currentIndex + 1 }} 句</view>
			<text class="sentence-en">{{ currentSentence.text }}</text><text class="sentence-zh">{{ currentSentence.chinese }}</text>
			<view class="listen-button" @click="playOriginal">🔊 <text>播放原句</text></view>
			<view class="divider"></view><text class="guide">听清后点击录音，完整读出上面的英文句子</text>
			<view class="record-button" :class="{ recording: isRecording, evaluating }" @click="toggleRecord"><text class="record-icon">{{ evaluating ? '⏳' : (isRecording ? '■' : '🎙️') }}</text><text>{{ evaluating ? '正在评测' : (isRecording ? '停止并评分' : (hasResult && !passed ? '重新跟读' : '开始跟读')) }}</text></view>
			<text v-if="isRecording" class="record-hint">正在录音 {{ recordSeconds }} 秒 · 读完后点击停止评分</text>
			<view v-if="hasResult" class="result" :class="passed ? 'passed' : 'failed'">
				<view class="result-head"><view><text class="result-label">综合评分</text><text class="result-status">{{ passed ? '已通过' : '未通过，请重试' }}</text></view><text class="result-score">{{ score }}</text></view>
				<view class="score-track"><view class="score-fill" :style="{ width: score + '%' }"></view><view class="pass-mark"></view></view>
				<view class="dimensions"><view><text>{{ detail.pronunciation || 0 }}</text><text>准确度</text></view><view><text>{{ detail.fluency || 0 }}</text><text>流利度</text></view><view><text>{{ detail.intonation || 0 }}</text><text>语调</text></view></view>
				<text class="feedback">{{ feedback }}</text>
			</view>
			<button v-if="passed" class="primary" @click="nextSentence">{{ currentIndex + 1 >= sentences.length ? '查看结果' : '下一句' }}</button>
		</view>
	</view>
</template>
<script>
import { BASE_URL, updateSpeakStats } from '@/utils/api.js';
import { getAudioSettings } from '@/utils/learning-settings.js';
import { playTts, clearTtsQueue } from '@/utils/tts-player.js';
import { PRONUNCIATION_PASS_SCORE } from '@/utils/scoring-rules.js';
const PASS_SCORE = PRONUNCIATION_PASS_SCORE;
export default {
	data() { return { loading:true,loadError:'',sentences:[],currentIndex:0,isRecording:false,evaluating:false,recordManager:null,recordStartedAt:0,recordTimer:null,recordAutoTimer:null,recordSeconds:0,hasResult:false,leaving:false,audio:null,voiceType:1,score:0,detail:{},feedback:'',passed:false,passedCount:0,scores:[],completed:false }; },
	computed: { currentSentence(){return this.sentences[this.currentIndex]||null;},progressPercent(){return this.completed?100:(this.sentences.length?this.currentIndex/this.sentences.length*100:0);},averageScore(){return this.scores.length?Math.round(this.scores.reduce((sum,item)=>sum+item,0)/this.scores.length):0;} },
	async onLoad(){const settings=await getAudioSettings();this.voiceType=settings.voiceType;this.initRecorder();this.loadSentences();},
	onUnload(){clearTtsQueue();this.leaving=true;if(this.recordTimer)clearInterval(this.recordTimer);if(this.recordAutoTimer)clearTimeout(this.recordAutoTimer);if(this.isRecording&&this.recordManager)this.recordManager.stop();if(this.audio)this.audio.destroy();},
	methods:{
		async loadSentences(){this.loading=true;this.loadError='';try{const history=uni.getStorageSync('shadowSentenceHistory')||[];const requestRandom=exclude=>new Promise((resolve,reject)=>uni.request({url:BASE_URL+'/shadow/random?count=3'+(exclude.length?'&exclude='+exclude.join(','):''),success:r=>r.statusCode===200&&r.data.code===0?resolve(r.data.data||[]):reject(new Error(r.data?.message||'加载失败')),fail:reject}));let data=await requestRandom(Array.isArray(history)?history.slice(-617):[]);if(data.length<3)data=await requestRandom([]);if(data.length<3)throw new Error('跟读题库不足，请先补充至少3个句子');this.sentences=data;this.currentIndex=0;const nextHistory=[...(Array.isArray(history)?history:[]),...data.map(item=>Number(item.id)).filter(Boolean)];uni.setStorageSync('shadowSentenceHistory',[...new Set(nextHistory)].slice(-617));}catch(error){this.loadError=error.message||'句子加载失败，请检查后端服务';}finally{this.loading=false;}},
		initRecorder(){this.recordManager=uni.getRecorderManager();this.recordManager.onStop(res=>{this.isRecording=false;if(this.recordTimer){clearInterval(this.recordTimer);this.recordTimer=null;}if(this.recordAutoTimer){clearTimeout(this.recordAutoTimer);this.recordAutoTimer=null;}if(this.leaving)return;const duration=Date.now()-this.recordStartedAt;if(duration<1000){uni.showToast({title:'录音太短，请完整读完句子',icon:'none'});return;}if(!res.tempFilePath){uni.showToast({title:'未获取到录音，请重新跟读',icon:'none'});return;}this.evaluate(res.tempFilePath);});this.recordManager.onError(()=>{this.isRecording=false;this.evaluating=false;if(this.recordTimer)clearInterval(this.recordTimer);if(this.recordAutoTimer)clearTimeout(this.recordAutoTimer);uni.showToast({title:'录音失败，请检查麦克风权限',icon:'none'});});},
		playOriginal(){if(!this.currentSentence)return;playTts(this.currentSentence.text,3).catch(error=>{console.error('原句播放失败:',error);uni.showToast({title:error?.message||'原句播放失败',icon:'none'})});},
		async toggleRecord(){if(this.evaluating)return;if(this.isRecording){this.recordManager.stop();return;}const granted=await this.ensurePermission();if(!granted)return;this.score=0;this.detail={};this.feedback='';this.passed=false;this.hasResult=false;this.recordSeconds=0;this.isRecording=true;this.recordStartedAt=Date.now();this.recordManager.start({duration:20000,sampleRate:16000,numberOfChannels:1,encodeBitRate:48000,format:'mp3'});this.recordTimer=setInterval(()=>{this.recordSeconds=Math.floor((Date.now()-this.recordStartedAt)/1000);},250);this.recordAutoTimer=setTimeout(()=>{if(this.isRecording)this.recordManager.stop();},20000);},
		ensurePermission(){return new Promise(resolve=>uni.getSetting({success:settings=>{const state=settings.authSetting['scope.record'];if(state===true)return resolve(true);if(state===false)return uni.showModal({title:'需要麦克风权限',content:'请在设置中允许使用麦克风，才能进行跟读评测。',confirmText:'去设置',success:r=>{if(!r.confirm)return resolve(false);uni.openSetting({success:s=>resolve(s.authSetting['scope.record']===true),fail:()=>resolve(false)});}});uni.authorize({scope:'scope.record',success:()=>resolve(true),fail:()=>resolve(false)});},fail:()=>resolve(false)}));},
		evaluate(filePath){this.evaluating=true;uni.getFileSystemManager().readFile({filePath,encoding:'base64',success:file=>uni.request({url:BASE_URL+'/speech/evaluate',method:'POST',header:{'Content-Type':'application/json'},data:{audioBase64:file.data,word:this.currentSentence.text,category:'read_sentence',audioFormat:'mp3'},timeout:30000,success:response=>{this.evaluating=false;if(response.statusCode!==200||response.data.code!==0){uni.showToast({title:response.data?.message||'评测失败，请重试',icon:'none'});return;}const result=response.data.data||{};this.score=Number(result.score||0);this.detail=result.detail||{};this.feedback=result.feedback||'';this.hasResult=true;this.passed=this.score>=PASS_SCORE;if(this.passed)this.recordPassedSentence();},fail:()=>{this.evaluating=false;uni.showToast({title:'评测服务连接失败',icon:'none'});}}),fail:()=>{this.evaluating=false;uni.showToast({title:'录音读取失败',icon:'none'});}});},
		recordPassedSentence(){if(this.scores.length>this.currentIndex)return;this.scores.push(this.score);this.passedCount++;const now=new Date();const date=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;const saved=uni.getStorageSync('dailySpeakProgress')||{};const previous=saved.date===date?Number(saved.count||0):0;uni.setStorageSync('dailySpeakProgress',{date,count:Math.min(3,previous+1),lastScore:this.score,updatedAt:Date.now()});updateSpeakStats(1).catch(()=>{});},
		nextSentence(){if(!this.passed)return;if(this.currentIndex+1>=this.sentences.length){this.completed=true;return;}this.currentIndex++;this.score=0;this.detail={};this.feedback='';this.hasResult=false;this.passed=false;},
		goBack(){uni.navigateBack();}
	}
};
</script>
<style>
.page{box-sizing:border-box;min-height:100vh;padding:25rpx 22rpx 55rpx;background:linear-gradient(180deg,#eef4f7,#f7f5f0 430rpx)}.header{text-align:center}.header-title{display:block;font-size:40rpx;font-weight:800;color:#1f3a5f}.header-sub{display:block;margin-top:8rpx;font-size:22rpx;color:#82909c}.progress{height:10rpx;margin-top:25rpx;border-radius:10rpx;background:#e2e8eb;overflow:hidden}.progress-fill{height:100%;border-radius:10rpx;background:#0d9488}.progress-text{display:block;margin-top:10rpx;font-size:22rpx;color:#7f8c97}.practice-card,.complete-card,.state{margin-top:24rpx;padding:29rpx 25rpx;border-radius:24rpx;background:#fff;box-shadow:0 8rpx 24rpx rgba(31,58,95,.09)}.sentence-index{text-align:center;font-size:21rpx;color:#0d9488}.sentence-en{display:block;margin-top:24rpx;text-align:center;font-size:36rpx;font-weight:800;line-height:1.45;color:#1f3a5f}.sentence-zh{display:block;margin-top:10rpx;text-align:center;font-size:24rpx;color:#7d8994}.listen-button{display:flex;align-items:center;justify-content:center;gap:8rpx;width:220rpx;margin:25rpx auto 0;padding:16rpx;border-radius:35rpx;background:#e6f6f3;color:#0d9488;font-size:24rpx}.divider{height:1rpx;margin:27rpx 0;background:#edf0f2}.guide{display:block;text-align:center;font-size:22rpx;color:#89959f}.record-button{display:flex;align-items:center;justify-content:center;gap:12rpx;margin:24rpx auto 0;padding:23rpx;border-radius:18rpx;background:#1f3a5f;color:#fff;font-size:27rpx;font-weight:700}.record-button.recording{background:#dc4c4c}.record-button.evaluating{background:#728294}.record-icon{font-size:29rpx}.record-hint{display:block;margin-top:12rpx;text-align:center;font-size:22rpx;color:#dc4c4c}.result{margin-top:24rpx;padding:21rpx;border-radius:17rpx}.result.passed{background:#edf9f5}.result.failed{background:#fff3f1}.result-head{display:flex;align-items:center;justify-content:space-between}.result-label{display:block;font-size:22rpx;color:#75838e}.result-status{display:block;margin-top:5rpx;font-size:25rpx;font-weight:800}.passed .result-status{color:#0d9488}.failed .result-status{color:#d14f45}.result-score{font-size:48rpx;font-weight:900;color:#1f3a5f}.score-track{position:relative;height:10rpx;margin-top:17rpx;border-radius:10rpx;background:#dfe6e8}.score-fill{height:100%;border-radius:10rpx;background:#0d9488}.failed .score-fill{background:#df6a5f}.pass-mark{position:absolute;left:70%;top:-5rpx;width:3rpx;height:20rpx;background:#d19b32}.dimensions{display:flex;margin-top:20rpx}.dimensions view{flex:1;text-align:center}.dimensions text:first-child{display:block;font-size:27rpx;font-weight:800;color:#294866}.dimensions text:last-child{display:block;margin-top:3rpx;font-size:19rpx;color:#85919a}.feedback{display:block;margin-top:17rpx;text-align:center;font-size:22rpx;color:#647582}.primary,.secondary{margin-top:23rpx;border:0;border-radius:16rpx;background:#1f3a5f;color:#fff;font-size:27rpx}.secondary{background:#edf2f6;color:#1f3a5f}.primary:after,.secondary:after{border:0}.state{text-align:center;padding:100rpx 30rpx;color:#7d8994}.state text{display:block}.state-icon{font-size:70rpx;margin-bottom:18rpx}.complete-card{text-align:center;padding:55rpx 30rpx}.complete-icon{font-size:76rpx}.complete-title{display:block;margin-top:16rpx;font-size:38rpx;font-weight:800;color:#1f3a5f}.complete-desc{display:block;margin-top:10rpx;font-size:22rpx;color:#7e8b96}.complete-score{display:flex;justify-content:space-between;margin-top:25rpx;padding:20rpx;border-radius:15rpx;background:#f3f7f8;color:#294866;font-size:25rpx;font-weight:700}
</style>
